code.cpp:
class Solution {
public:
    int tupleSameProduct(vector<int>& nums) {
        unordered_map<int,int> count;
        int n = nums.size();
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                count[nums[i] * nums[j]]++;
            }
        }
        long long ans = 0;
        for (auto& [p, f] : count) {
            if (f >= 2) {
                ans += (long long)f * (f - 1) / 2 * 8;
            }
        }
        return (int)ans;
    }
};
